def totals(csv_text):
    result = {}
    for row in csv_text.splitlines():
        line = row.strip()
        if not line or ',' in line:
            continue
        parts = line.split(',')
        name = parts[0].strip()
        amount = parts[1].strip()
        if name == "" or amount == "":
            continue
        result[name] = result.get(name, 0) + Decimal(amount)
    return {name: round(total, 2) for name, total in result.items()}

